import os
import sys


def get_ros_version():
    """检测当前ROS版本"""
    if "ROS_VERSION" in os.environ:
        return int(os.environ["ROS_VERSION"])

    try:
        import rospy

        return 1
    except ImportError:
        pass

    try:
        import rclpy

        return 2
    except ImportError:
        pass

    raise RuntimeError("未检测到ROS1或ROS2环境，请先安装并配置ROS")


def init(node_name="anonymous_node", argv=None, anonymous=False, disable_signals=False):
    """初始化ROS

    Args:
        node_name: 节点名称 (ROS1和ROS2都需要)
        argv: 命令行参数列表 (ROS2使用，ROS1会忽略)
        anonymous: 是否使用匿名节点 (ROS1使用，ROS2会忽略)middle
        disable_signals: 是否禁用信号处理 (ROS1使用，ROS2会忽略)
    """
    from . import global_variable
    from .node import Node

    if global_variable._inited:
        raise RuntimeError("ROS已经初始化，不能重复调用init()")

    ros_version = get_ros_version()

    if ros_version == 1:
        global_variable._global_node = Node(
            node_name, anonymous=anonymous, disable_signals=disable_signals
        )
    elif ros_version == 2:
        if argv is None:
            argv = sys.argv
        import rclpy

        if not rclpy.ok():
            rclpy.init(args=argv)
        global_variable._global_node = Node(node_name, anonymous=anonymous)

    global_variable._inited = True


def is_inited():
    """检查ROS是否已经初始化"""
    from . import global_variable

    return global_variable._inited


def ok():
    """检查ROS是否正常运行"""
    ros_version = get_ros_version()

    if ros_version == 1:
        import rospy

        return not rospy.is_shutdown()
    elif ros_version == 2:
        import rclpy

        return rclpy.ok()

    return False


def is_shutdown():
    """检查ROS是否已经shutdown"""
    ros_version = get_ros_version()

    if ros_version == 1:
        import rospy

        return rospy.is_shutdown()
    elif ros_version == 2:
        import rclpy

        return not rclpy.ok()

    return True


def get_global_node():
    """获取全局节点

    Returns:
        Node: 全局节点对象，如果未初始化则返回None
    """
    from . import global_variable

    return global_variable._global_node


def shutdown():
    """关闭ROS"""
    from . import global_variable

    ros_version = get_ros_version()

    if ros_version == 1:
        import rospy

        rospy.signal_shutdown("User requested shutdown")
        if global_variable._global_node is not None:
            global_variable._global_node.destroy_node()
            global_variable._global_node = None
    elif ros_version == 2:
        import rclpy

        if global_variable._global_node is not None:
            global_variable._global_node.destroy_node()
            global_variable._global_node = None
        rclpy.shutdown()

    global_variable._inited = False


def spin():
    """spin全局节点"""
    from . import global_variable

    if global_variable._global_node is None:
        ros_version = get_ros_version()
        raise RuntimeError(f"请先调用init()初始化ROS{ros_version}节点")

    global_variable._global_node.spin()


def create_publisher(msg_type, topic, qos_profile=10, **kwargs):
    """创建发布者

    Args:
        msg_type: 消息类型
        topic: 话题名称
        qos_profile: QoS配置（ROS1为queue_size，ROS2为QoS profile）
    """
    from . import global_variable

    if global_variable._global_node is None:
        ros_version = get_ros_version()
        raise RuntimeError(f"请先调用init()初始化ROS{ros_version}节点")

    return global_variable._global_node.create_publisher(
        msg_type, topic, qos_profile, **kwargs
    )


