def create_rate(frequency):
    """创建频率控制器

    Args:
        frequency: 频率 (Hz)

    Returns:
        Rate: 频率控制器对象
    """
    from .rate import Rate

    return Rate(frequency)


def create_timer(period, callback):
    """创建定时器

    Args:
        period: 定时周期 (秒)
        callback: 回调函数

    Returns:
        Timer: 定时器对象
    """
    from .timer import Timer

    return Timer(period, callback)
